    def decode_ownable_invalid_owner_error(self, data: str) -> tuple[Any, ...]:
        """Decodes OwnableInvalidOwner(address) custom error arguments."""
        raw = bytes.fromhex(data.removeprefix("0x"))
        if raw[:4] != bytes.fromhex("1e4fbdf7"):
            raise ValueError("Custom error selector mismatch")
        return _strict_abi_decode(["address"], raw[4:])

    def decode_ownable_unauthorized_account_error(self, data: str) -> tuple[Any, ...]:
        """Decodes OwnableUnauthorizedAccount(address) custom error arguments."""
        raw = bytes.fromhex(data.removeprefix("0x"))
        if raw[:4] != bytes.fromhex("118cdaa7"):
            raise ValueError("Custom error selector mismatch")
        return _strict_abi_decode(["address"], raw[4:])

    def decode_value_out_of_range_error(self, data: str) -> tuple[Any, ...]:
        """Decodes ValueOutOfRange() custom error arguments."""
        raw = bytes.fromhex(data.removeprefix("0x"))
        if raw[:4] != bytes.fromhex("4eb4f9fb"):
            raise ValueError("Custom error selector mismatch")
        return _strict_abi_decode([], raw[4:])

    @staticmethod
    def build_deployment(w3: Web3, bytecode: str, transaction: dict[str, Any]) -> dict[str, Any]:
        """Builds deployment with caller-supplied bytecode and typed constructor arguments."""
        if transaction.get("value", 0):
            raise ValueError("Constructor is not payable")
        contract = w3.eth.contract(abi=BOOTSTRAPCONFIG_ABI, bytecode=bytecode)
        return contract.constructor().build_transaction(transaction)
